import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.DSQXGnvq.js";const c=JSON.parse('{"title":"示例介绍","description":"","frontmatter":{},"headers":[],"relativePath":"example-introduction.md","filePath":"example-introduction.md"}'),l={name:"example-introduction.md"};function o(n,t,p,r,h,k){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="示例介绍" tabindex="-1">示例介绍 <a class="header-anchor" href="#示例介绍" aria-label="Permalink to &quot;示例介绍&quot;">​</a></h1><p>本节通过典型电路示例概述 PySpice 的用法，这些示例也可作为学习材料。</p><p>这些示例通常不涉及高级 Python 编程。你只需了解 Python 编程基础以及 NumPy 和 Matplotlib 的基本用法。但绘制复杂图形可能需要较高的 Matplotlib 技能。</p><h2 id="如何学习-python" tabindex="-1">如何学习 Python <a class="header-anchor" href="#如何学习-python" aria-label="Permalink to &quot;如何学习 Python&quot;">​</a></h2><p>以下是一些学习 Python 和科学计算框架的链接：</p><ul><li><a href="https://docs.python.org/3/tutorial/index.html" target="_blank" rel="noreferrer">Python 教程</a></li><li><a href="http://matplotlib.org/users/pyplot_tutorial.html" target="_blank" rel="noreferrer">Pyplot 教程</a></li><li><a href="https://scipy-lectures.github.io/" target="_blank" rel="noreferrer">Python 科学笔记</a></li><li><a href="http://nbviewer.ipython.org/github/jrjohansson/scientific-python-lectures/tree/master/" target="_blank" rel="noreferrer">科学 Python 讲座</a></li></ul><h2 id="如何运行这些示例" tabindex="-1">如何运行这些示例 <a class="header-anchor" href="#如何运行这些示例" aria-label="Permalink to &quot;如何运行这些示例&quot;">​</a></h2><p>有几种运行示例的方式：以脚本方式从终端运行、在 IPython 交互环境中运行、或在浏览器中使用 Jupyter Notebook 运行。各有其优缺点。脚本适合用编辑器修改文件，交互环境适合交互式调试。</p><p>从终端运行示例：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/.../foo.py</span></span></code></pre></div><p>启动交互式 IPython 环境：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipython</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --matplotlib</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 启用 matplotlib 集成</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipython</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --matplotlib-qt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 启用 matplotlib qt4 后端集成</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipython</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qtconsole</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 启动 qtconsole GUI 应用</span></span></code></pre></div><p>然后使用魔法命令运行示例：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run examples</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">..</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">foo.py</span></span></code></pre></div><p>在浏览器中启动 Jupyter notebook：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipython</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notebook</span></span></code></pre></div><p>使用 Jupyter notebook 时，建议使用可嵌入 notebook 文件的 Matplotlib 后端。在 notebook 开头添加：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">matplotlib inline</span></span></code></pre></div><p>然后可以复制粘贴代码块并执行。</p><h2 id="如何编写网表" tabindex="-1">如何编写网表 <a class="header-anchor" href="#如何编写网表" aria-label="Permalink to &quot;如何编写网表&quot;">​</a></h2><p>从零编写网表并不容易。最佳做法是先画草图并标注节点。你也可以使用 KiCad 等原理图捕获程序，将网表导出为 SPICE 格式。</p><p>还可以使用 <a href="https://devbisme.github.io/skidl/" target="_blank" rel="noreferrer">SKiDL</a>，这是一个 Python 模块，可以用简洁的方式描述电子电路和元器件的互连。参考完整示例：<a href="https://github.com/devbisme/skidl" target="_blank" rel="noreferrer">https://github.com/devbisme/skidl</a></p><h2 id="如何绘制电路" tabindex="-1">如何绘制电路 <a class="header-anchor" href="#如何绘制电路" aria-label="Permalink to &quot;如何绘制电路&quot;">​</a></h2><p>有几种绘制电路的方式，取决于你需要高质量图形还是快速草图：</p><ul><li>在纸上绘制电路并扫描，或使用数位板。如果技艺娴熟，这可以很美观</li><li>使用 KiCad 等原理图编辑器导出为 SVG。KiCad 允许选择线宽、颜色或黑色墨水，以及去除边框。可以用 Inkscape 编辑 SVG</li><li>使用 <a href="https://schemdraw.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">Schemdraw</a>，一个用 Python 生成高质量电路原理图的包（SVG）</li><li>使用复杂的图形语言如 <a href="https://ctan.org/pkg/circuitikz?lang=en" target="_blank" rel="noreferrer">CircuiTikZ</a> 或 <a href="https://ece.uwaterloo.ca/~aplevich/Circuit_macros" target="_blank" rel="noreferrer">Circuit_macros</a>。前者是 LaTeX Tikz 包，后者使用 M4 宏和 LaTeX 渲染电路。这些工具适合出版物或书籍</li></ul><p>SVG 格式适合网络发布，PDF 适合纸质出版。主要区别在于字体处理，二者可相互转换。</p><h2 id="用-python-文件还是-jupyter-notebook" tabindex="-1">用 Python 文件还是 Jupyter Notebook？ <a class="header-anchor" href="#用-python-文件还是-jupyter-notebook" aria-label="Permalink to &quot;用 Python 文件还是 Jupyter Notebook？&quot;">​</a></h2><p><a href="https://jupyter.org" target="_blank" rel="noreferrer">JupyterLab</a> 提供类似 Matlab 的 Web 应用环境。</p><p>简单来说，如果你需要类似 Matlab 的环境，Jupyter 是一个不错的选择。但如果你要做复杂编程，标准 Python 文件更好。</p><p>从技术上讲，Jupyter Notebook 是一个 JSON 文件——在文本文件中编码的 Python 字典，内含 Python 代码、Markdown 文本或图片（base64 编码）的单元格。</p><p>从 Git 的角度看，纯 Python 文件比嵌入代码和输出的 JSON 文件更适合版本管理。</p><p>作为替代方案，可以实现<strong>文学编程</strong>的概念——在源文件中混合富文本和代码。某些实现将富文本嵌入注释中，其他则需要工具分离文本和代码。概念上与 Jupyter Notebook 类似，但 notebook 可以嵌入结果，且不便于直接阅读。</p><p>PySpice 示例使用 Pyterate 文档生成器，其中文件是纯 Python 文件，文本以注释形式编码。你也可以考虑 Pweave 作为替代。</p><p>Jupyter Notebook 的缺点：</p><ul><li>强制使用浏览器作为编辑器（但可以使用 Emacs IPython Notebook 等编辑器插件）</li><li>JupyterLab 作为代码编辑器功能较弱，缺少补全、linting 等 IDE 常用功能</li><li>JupyterLab 需要扩展才能获得交互式图形</li><li>不应提交输出内容（可使用 <code>jupyter nbconvert --ClearOutputPreprocessor.enabled=True</code> 清除）</li><li>JSON diff 的可读性差</li><li>对文件进行文本替换存在风险</li><li>Jupyter 在 OSX 持续集成虚拟机上会挂起，无法运行 notebook</li><li>JupyterLab 中 SVG 图片支持似乎有误</li></ul>`,35)])])}const y=a(l,[["render",o]]);export{c as __pageData,y as default};
